"use strict";exports.id=7725,exports.ids=[7725],exports.modules={77725:(e,t,i)=>{i.d(t,{j:()=>n});let o={orange:"#E8621A",gold:"#C9A84C",purple:"#A855F7",teal:"#0F505A"},n=[{id:"common-sense-in-the-workplace",num:"01",tag:"Foundation",title:"Common Sense in the Workplace",subtitle:"Awareness \xb7 Communication \xb7 Vibe Hygiene",color:o.orange,totalTime:"~2.5 hrs",description:"The foundational track. Before de-escalation, self-mastery, or team cohesion is possible, every professional needs a baseline level of emotional awareness, communication clarity, and personal vibe hygiene.",lessons:[{id:"b01-l01",num:"01",title:"The Awareness Gap",duration:"20 min",type:"video",description:"Most workplace friction isn't caused by bad people — it's caused by unawareness.",objectives:["Define the Awareness Gap and why it generates most professional friction","Distinguish between intent, behavior, and impact","Identify your default awareness level under stress"],content:["The Awareness Gap is the distance between who you think you're being and who others actually experience. Most workplace friction isn't caused by bad people—it's caused by unawareness.","We operate from intention ('I was just being honest') while others receive behavior ('that comment felt dismissive'). Neither is wrong—both are real. The professional who closes this gap becomes someone others want to work with.","Neuroscience tells us that under stress, the prefrontal cortex—responsible for self-monitoring—goes offline first. Emotional intelligence is the skill of keeping it online when it matters most.","Your Awareness Inventory: For the next 48 hours, practice a single question after every meaningful interaction—'What did they experience from me?' Not what you intended. What they received."],tool:"Awareness Inventory Log",quiz:[{q:"The Awareness Gap describes the distance between:",options:["Your intentions and how others experience your behavior","Your skill level and your manager's expectations","What you say and what you mean","Your current role and the role you want"],correct:0},{q:"Under stress, which brain region goes offline first?",options:["Amygdala","Cerebellum","Prefrontal cortex","Hippocampus"],correct:2},{q:"The core professional skill taught in this module is:",options:["Assertive communication","Keeping the self-monitoring brain online under stress","Reading body language","Time management"],correct:1}]},{id:"b01-l02",num:"02",title:"Emotional Signals at Work",duration:"22 min",type:"video",description:"Emotions are data, not drama. This module teaches you to read your own emotional signals accurately — before they read you.",objectives:["Identify the four primary emotion families and their workplace triggers","Use the Body-Emotion-Behavior chain to anticipate your responses","Develop a personal emotion vocabulary that increases precision"],content:["Emotions are not problems to eliminate—they are your nervous system's real-time assessment of your environment. They are data, not drama.","The four primary emotion families (Fear, Anger, Sadness, Shame) each provide specific information about boundaries, values, or safety.","When you identify a signal early, you can respond. When you ignore it, the signal increases in volume until it becomes behavior you regret."],tool:"Emotion Signal Map",quiz:[{q:"In this module, emotions are described as:",options:["Weaknesses","Data","Social signals","Random noise"],correct:1}]},{id:"b01-l03",num:"03",title:"Communication Architecture",duration:"25 min",type:"workshop",description:"The structure behind clear professional communication.",objectives:["Apply the three-layer communication model (content, context, subtext)","Distinguish between assertive, passive, and aggressive communication patterns","Practice the Clarity Frame: Observation — Impact — Request"],content:["Every workplace communication operates on three simultaneous layers: Content (what is said), Context (why it's being said), and Subtext (the emotional frequency it's said with).","Most friction occurs when we ignore Context and Subtext. The 'Clarity Frame' ensures all three layers are aligned."],tool:"Clarity Frame Worksheet",quiz:[{q:"The three layers of communication in this model are:",options:["Verbal/nonverbal/written","Content, context, and subtext","Speaker, listener, environment","Thinking, feeling, acting"],correct:1}]},{id:"b01-l04",num:"04",title:"Trigger Mapping",duration:"20 min",type:"workshop",description:"Know your triggers before they know you.",objectives:["Define what a workplace trigger is at the neurological level","Identify your top three personal trigger categories","Build a Trigger Map"],content:["A trigger is not a feeling—it's a threat signal sent to your amygdala that hijacks your prefrontal cortex. It happens in under 200 milliseconds.","By mapping your recurring triggers, you move them from the unconscious 'blind spot' to the conscious 'observed environment,' allowing for a pause."],tool:"Personal Trigger Map",quiz:[{q:"A trigger fires in the amygdala in approximately:",options:["2 seconds","500 milliseconds","Under 200 milliseconds","1-2 minutes"],correct:2}]},{id:"b01-l05",num:"05",title:"Vibe Hygiene",duration:"18 min",type:"video",description:"Your nervous system is contagious.",objectives:["Understand nervous system co-regulation","Build a personalized Vibe Hygiene stack","Apply Evening Revision"],content:["Nervous systems are contagious—mirror neurons mean your colleagues' brains are literally affected by your physiological state. This is known as co-regulation.","If you are leaking stress, you are creating a threat environment for your team. Vibe Hygiene is the practice of intentional regulation for the sake of the collective."],tool:"Vibe Hygiene Daily Stack",quiz:[{q:"Why is a dysregulated leader harmful to their team?",options:["Poor decision making","Mirror neurons cause physiological contagion","They speak louder","They cancel meetings"],correct:1}]},{id:"b01-l06",num:"06",title:"Live Integration Session",duration:"60 min",type:"live",isLive:!0,description:"Live group session with a Vibe Hyr facilitator.",objectives:["Apply concepts to case studies","Receive feedback","Build Integration Commitment"],content:["This live session is your integration point for all five Track 01 modules."],tool:"Track 01 Integration Commitment",quiz:[]}]},{id:"from-reaction-to-response",num:"02",tag:"De-Escalation",title:"From Reaction to Response",subtitle:"The Escalation Ladder \xb7 Stage Intervention \xb7 Pattern Interrupts",color:o.gold,totalTime:"~2.5 hrs",description:"Conflict isn't the problem. Unconscious escalation is. This track installs a five-stage Escalation Ladder.",lessons:[{id:"b02-l01",num:"01",title:"The Reactivity Spectrum",duration:"18 min",type:"video",description:"Why smart professionals do things they immediately regret.",objectives:["Define Reactivity Spectrum","Identify point of no return","Understand logic loss"],content:["The Reactivity Spectrum runs from baseline calm to amygdala hijack."],tool:"Reactivity Spectrum Self-Assessment",quiz:[{q:"Once in a full amygdala hijack, which is available?",options:["Reasoning","Empathy","Physiological regulation","Problem solving"],correct:2}]},{id:"b02-l02",num:"02",title:"The Escalation Ladder",duration:"22 min",type:"workshop",description:"A five-stage conflict map.",objectives:["Identify all five stages","Map recent conflict","Calculate intervention windows"],content:["Stage 1 Friction, Stage 2 Tension, Stage 3 Conflict, Stage 4 Crisis, Stage 5 Rupture."],tool:"Escalation Ladder Reference Card",quiz:[{q:"At Stage 3 (Conflict), recommended intervention is:",options:["State position","Pause protocol/recess","Increase logic","Express emotion"],correct:1}]},{id:"b02-l03",num:"03",title:"Stage 1 Intervention",duration:"20 min",type:"workshop",description:"The most powerful place to intervene is Stage 1.",objectives:["Master toolkit","Practice conversations","Build proactive habits"],content:["Four Stage 1 responses: Acknowledge, Clarify, Redirect, Release."],tool:"Stage 1 Conversation Scripts",quiz:[{q:"Why is Stage 1 highest-leverage?",options:["Easier intensity","Early intervention costs little","Only point possible","Impresses colleagues"],correct:1}]},{id:"b02-l04",num:"04",title:"Pattern Interrupts",duration:"22 min",type:"workshop",description:"Patterns are more dangerous than single events.",objectives:["Identify recurring patterns","Map sequence","Design interrupts"],content:["The goal is not to eliminate the trigger — it's to break the automated chain from trigger → old behavior."],tool:"Pattern Interrupt Design Template",quiz:[{q:"A conflict pattern is defined as:",options:["Single intense event","Repeating trigger-response-outcome loop","Disagreement > 1 day","Multi-party conflict"],correct:1}]},{id:"b02-l05",num:"05",title:"Response Protocols",duration:"20 min",type:"video",description:"Pre-built response frameworks.",objectives:["Apply PAUSE protocol","Use REFRAME script","Master EXIT protocol"],content:["The PAUSE Protocol: Physiological, Acknowledge, Understand, Select, Execute."],tool:"Response Protocol Quick-Reference Card",quiz:[{q:"In PAUSE, 'A' stands for:",options:["Assert","Acknowledge internal state","Ask question","Analyze"],correct:1}]},{id:"b02-l06",num:"06",title:"Live De-Escalation Workshop",duration:"60 min",type:"live",isLive:!0,description:"Live facilitated workshop.",objectives:["Practice live","Receive feedback","Build protocol card"],content:["This live workshop uses structured roleplay."],tool:"Personal De-Escalation Protocol Card",quiz:[]}]},{id:"know-yourself-lead-yourself",num:"03",tag:"Self Mastery",title:"Know Yourself, Lead Yourself",subtitle:"Identity Architecture \xb7 Assumption Audit \xb7 90-Day Shift Plan",color:o.purple,totalTime:"~3 hrs",description:"Leadership begins with self-knowledge. This track uses neuroscience and the Law of Assumption.",lessons:[{id:"b03-l01",num:"01",title:"Identity Architecture",duration:"22 min",type:"video",description:"Professional behavior is downstream of self-concept.",objectives:["Define identity as assumption","Three layers of identity","Locate gap"],content:["Identity is not who you are — it's who you assume yourself to be."],tool:"Identity Architecture Map",quiz:[{q:"In this framework, identity is:",options:["Fixed traits","Habitual assumption","Achievements","Perception"],correct:1}]},{id:"b03-l02",num:"02",title:"The Four Archetypes",duration:"25 min",type:"workshop",description:"Four identity archetypes: Performer, Protector, Prover, Sovereign.",objectives:["Identify archetypes","Recognize driving archetype","Understand costs"],content:["The goal is not to eliminate archetypes — it's to know which one is driving and have choice."],tool:"Archetype Recognition Journal",quiz:[{q:"The Sovereign archetype's core belief is:",options:["I am my results","Safety is not standing out","Never inadequante","Value is not contingent"],correct:3}]},{id:"b03-l03",num:"03",title:"The Assumption Audit",duration:"22 min",type:"workshop",description:"Surface unconscious assumptions.",objectives:["Define assumption","Complete audit","Identify limiters"],content:["An assumption is not a belief you hold — it's a belief that holds you."],tool:"Professional Assumption Audit",quiz:[{q:"A limiting assumption differs from a belief because it:",options:["Is false","Consciously held","Instructs the RAS","Contextual"],correct:2}]},{id:"b03-l04",num:"04",title:"The 90-Day Shift Plan",duration:"25 min",type:"workshop",description:"A structured 90-day protocol for installing a new professional identity assumption.",objectives:["Design 90-day plan","Build identity bridge","Create accountability structures"],content:["The 90-Day Shift operates in three phases: Foundation (days 1–30), Application (days 31–60), and Integration (days 61–90)."],tool:"90-Day Shift Planner",quiz:[{q:"The 90-Day Shift moves through how many phases?",options:["Two","Three","Four","One"],correct:1}]},{id:"b03-l05",num:"05",title:"Revision and the Law of Assumption",duration:"22 min",type:"video",description:"The Law of Assumption applied to professional identity: how to revise your self-concept and watch behavior follow.",objectives:["Understand revision as neural reconsolidation","Apply Evening Revision protocol","Track identity evidence"],content:["Revision isn't positive thinking — it's a neurological process of reconsolidating memory with a corrected self-assumption."],tool:"Evening Revision Protocol",quiz:[{q:"Revision works by:",options:["Pretending past events didn't happen","Neurologically reconsolidating memory with an updated self-assumption","Affirmations","Visualization only"],correct:1}]},{id:"b03-l06",num:"06",title:"Live Self-Mastery Session",duration:"60 min",type:"live",isLive:!0,description:"Live facilitated session: identity architecture, assumption audit, and 90-day shift integration.",objectives:["Map identity architecture","Receive coaching on assumptions","Finalize 90-day shift plan"],content:["This live session integrates all five Track 03 modules into a personal development action plan."],tool:"Personal 90-Day Shift Commitment",quiz:[]}]},{id:"the-high-frequency-team",num:"04",tag:"Team Excellence",title:"The High-Frequency Team",subtitle:"Co-Regulation \xb7 Collective Assumptions \xb7 Accountability",color:o.teal,totalTime:"~3 hrs",description:"High performance is a byproduct of high frequency. This track builds the team architecture for sustained excellence.",lessons:[{id:"b04-l01",num:"01",title:"Team Frequency Mapping",duration:"18 min",type:"video",description:"Teams have a collective frequency. This module teaches you to map it.",objectives:["Define team frequency","Identify states","Nervous system co-regulation"],content:["Team frequency is the collective physiological and emotional state of the group."],tool:"Team Frequency Map",quiz:[{q:"Nervous system co-regulation means:",options:["Natural balance","Stress responses synchronize with leader","Individual regulation unnecessary","Flow is one way"],correct:1}]},{id:"b04-l02",num:"02",title:"Collective Assumptions",duration:"22 min",type:"video",description:"Teams don't just have shared goals — they have shared assumptions. These assumptions determine collective performance.",objectives:["Define collective assumption","Identify team assumption patterns","Map limiting vs. empowering team beliefs"],content:["A team is a shared nervous system running on collective assumptions. What the group believes about itself determines what the group becomes."],tool:"Team Assumption Audit",quiz:[{q:"A team's collective assumption most directly determines:",options:["Task assignment","Meeting frequency","Collective performance ceiling","Leadership hierarchy"],correct:2}]},{id:"b04-l03",num:"03",title:"The Accountability Architecture",duration:"25 min",type:"workshop",description:"High-frequency teams are self-accountable. This module builds the systems that make accountability intrinsic, not imposed.",objectives:["Distinguish intrinsic vs. imposed accountability","Build team accountability agreements","Design accountability rhythms"],content:["Imposed accountability requires a monitor. Intrinsic accountability is built into the team's identity."],tool:"Team Accountability Agreement Template",quiz:[{q:"Intrinsic accountability differs from imposed accountability because:",options:["It requires external pressure","It is built into team identity rather than requiring monitoring","It uses punishment","It is performance-based"],correct:1}]},{id:"b04-l04",num:"04",title:"Communication at High Frequency",duration:"22 min",type:"workshop",description:"The communication patterns of high-frequency teams — how they speak, listen, and resolve friction before it escalates.",objectives:["Identify high-frequency communication markers","Apply the Clarity Protocol","Build feedback culture"],content:["High-frequency teams have a low friction-to-resolution ratio. Not because they have fewer conflicts, but because they resolve them faster."],tool:"Team Communication Clarity Protocol",quiz:[{q:"High-frequency teams resolve friction faster because:",options:["They avoid conflict","Low friction-to-resolution ratio: fast resolution protocols, not fewer conflicts","Leadership is stronger","They communicate less"],correct:1}]},{id:"b04-l05",num:"05",title:"Sustaining Team Excellence",duration:"20 min",type:"video",description:"The maintenance architecture that keeps high-frequency teams performing at peak — preventing drift and energetic decay.",objectives:["Identify drift signals","Build maintenance rhythms","Design team renewal practices"],content:["All high-performing systems drift without maintenance. Team frequency is no exception."],tool:"Team Frequency Maintenance Calendar",quiz:[{q:"Team frequency drift is best addressed by:",options:["Replacing team members","Performance improvement plans","Proactive maintenance rhythms — preventing drift before it becomes visible","Retreats only"],correct:2}]},{id:"b04-l06",num:"06",title:"Live Team Excellence Workshop",duration:"60 min",type:"live",isLive:!0,description:"Live facilitated group workshop for team frequency mapping, assumption audit, and accountability architecture.",objectives:["Complete team frequency map","Build collective accountability agreement","Design team maintenance rhythm"],content:["This live workshop brings the entire Track 04 curriculum into a shared team experience."],tool:"Team Frequency Action Plan",quiz:[]}]}]}};